'use strict';
(() => {
  const $ = (id) => document.getElementById(id);
  const locale = document.documentElement.lang;
  const messages = window.NOCTURNE_I18N[locale] || window.NOCTURNE_I18N.ko;
  const t = (key,values={}) => messages[key].replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??''));
  function switchLanguage(next){if(!window.NOCTURNE_I18N[next])return;savePosition();const root=new URL('.',document.baseURI);const target=new URL(next==='ko'?'./':`${next}/`,root);target.hash=location.hash;location.assign(target.href);}
  $('language-select').addEventListener('change',e=>switchLanguage(e.target.value));
  $('reader-language-select').addEventListener('change',e=>switchLanguage(e.target.value));
  $('reader-language').addEventListener('click',()=>{const select=$('reader-language-select');select.value=locale;openDialog('language-dialog');});
  const KEY = 'nocturne.reader.v1';
  const defaults = {font:'serif',size:22,line:1.9,width:680,brightness:94};
  const clamp = (v,min,max) => Math.min(max,Math.max(min,Number(v)||min));
  const esc = (v) => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let storageOk=true, saved={settings:{...defaults},positions:{},bookmarks:[],lastBookId:null};
  try { const raw=JSON.parse(localStorage.getItem(KEY)||'null'); if(raw&&typeof raw==='object'){
    saved.settings={...defaults,...raw.settings}; saved.positions=raw.positions&&typeof raw.positions==='object'?raw.positions:{};
    saved.bookmarks=Array.isArray(raw.bookmarks)?raw.bookmarks.filter(b=>b&&typeof b.bookId==='string'&&Number.isInteger(b.chapter)&&Number.isInteger(b.paragraph)):[];
    saved.lastBookId=typeof raw.lastBookId==='string'?raw.lastBookId:null;
  }} catch { storageOk=false; }
  saved.settings={font:saved.settings.font==='sans'?'sans':'serif',size:clamp(saved.settings.size,16,32),line:clamp(saved.settings.line,1.5,2.3),width:clamp(saved.settings.width,480,860),brightness:clamp(saved.settings.brightness,65,100)};
  let catalog=[], current=null, chapterIndex=0, openToken=0, filter='all', restoring=false, focusMode=false, scrollTimer, toastTimer;
  const booksCache=new Map();
  const palette=[['#142b29','#d4bd83'],['#363129','#d5c5a5'],['#262c30','#b9c7be'],['#31352a','#d0c59f'],['#342839','#cfb1c0'],['#30272c','#d2b9ac'],['#28302c','#b9c6b4'],['#202e3a','#b9c5d2'],['#332226','#d1a3a6'],['#2e3026','#c5c5a0'],['#252c3c','#b5bbd2'],['#2e2b35','#c7bbc9']];
  const genreLabels=Object.fromEntries(['literary','romance','gothic','fantasy','adventure','horror','mystery','science-fiction'].map(key=>[key,t(key)]));
  function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));storageOk=true;}catch{if(storageOk)toast(t('storageError'));storageOk=false;}}
  function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2600);}
  function duration(min){const rounded=Math.max(0,Math.round(min)),hours=Math.floor(rounded/60),minutes=rounded%60;return hours?`${t('hour',{n:hours})}${minutes?` ${t('minute',{n:minutes})}`:''}`:t('minute',{n:minutes});}
  function cover(book,index=0){const colors=palette[index%palette.length];return `<div class="book-cover cover-design-${index%4}" style="--cover-bg:${colors[0]};--cover-accent:${colors[1]}" aria-hidden="true"><span class="cover-edition">NOCTURNE · ORIGINALS</span><div class="cover-title">${esc(book.title)}</div><div class="cover-lineart"></div><div class="cover-author">${esc(book.author)}</div><span class="cover-year">${esc(book.publishedYear)}</span></div>`;}
  function matches(book){const q=$('search').value.trim().toLocaleLowerCase();const genre=book.genre;const inGenre=filter==='all'||filter==='classic'&&['literary','romance'].includes(genre)||filter==='gothic'&&['gothic','mystery','horror'].includes(genre)||filter==='adventure'&&['adventure','fantasy'].includes(genre)||filter==='scifi'&&genre==='science-fiction';return inGenre&&(!q||`${book.title} ${book.author} ${book.publishedYear}`.toLocaleLowerCase().includes(q));}
  function renderShelf(){
    const shown=catalog.filter(matches);$('result-count').textContent=t('books',{n:shown.length});$('empty-state').hidden=shown.length>0;
    $('book-grid').innerHTML=shown.map(book=>{const i=catalog.indexOf(book),position=saved.positions[book.id],progress=position?clamp(position.percent,0,100):0;return `<button class="book-card" data-book="${esc(book.id)}" aria-label="${esc(t('readLabel',{title:book.title}))}"><div class="cover-wrap">${cover(book,i)}${progress>0?`<span class="saved-progress">${t('readPercent',{n:Math.round(progress)})}</span>`:''}</div><span class="book-card-title" lang="en">${esc(book.title)}</span><span class="book-card-author" lang="en">${esc(book.author)}</span><span class="book-card-meta"><span>${esc(genreLabels[book.genre]||t('classic'))} · ${esc(book.publishedYear)}</span><span>${esc(t('about',{time:duration(book.readingMinutes)}))}</span></span></button>`;}).join('');
    $('bookmark-count').textContent=saved.bookmarks.length;
    const book=catalog.find(b=>b.id===saved.lastBookId),position=book&&saved.positions[book.id];$('continue-section').hidden=!position;
    if(position){$('continue-reading').innerHTML=`<span><strong lang="en">${esc(book.title)}</strong><small>${esc(book.author)} · ${t('continue')}</small></span><span class="continue-percent">${Math.round(clamp(position.percent,0,100))}%<span class="mini-progress"><span style="width:${clamp(position.percent,0,100)}%"></span></span></span><span aria-hidden="true">↗</span>`;}
  }
  function renderFeatured(){const book=catalog.find(b=>b.id==='great-gatsby')||catalog[0];if(!book)return;$('featured').innerHTML=`<div class="featured-art">${cover(book,catalog.indexOf(book))}</div><div class="featured-copy"><p class="eyebrow">${t('featured')}</p><h2 lang="en">${esc(book.title)}</h2><p class="featured-author">${esc(book.author)} <span>· ${esc(book.publishedYear)}</span></p><p class="featured-description">${esc(t('description'))}</p><div class="featured-meta"><span>${t('englishOriginal')}</span><span>${esc(t('chapters',{n:book.mainChapterCount||book.chapterCount,time:t('about',{time:duration(book.readingMinutes)})}))}</span></div><button class="primary-button" data-book="${esc(book.id)}">${t('readOriginal')} <span aria-hidden="true">↗</span></button></div><span class="featured-number">NO. 001 / ${String(catalog.length).padStart(3,'0')}</span>`;}
  async function fetchJson(path){const response=await fetch(path,{signal:AbortSignal.timeout(25000)});if(!response.ok)throw Error(`HTTP ${response.status}`);return response.json();}
  async function getBook(meta){if(booksCache.has(meta.id))return booksCache.get(meta.id);const data=await fetchJson(`data/${meta.file}`);if(data.id!==meta.id||!Array.isArray(data.chapters)||!data.chapters.length||data.chapters.some(c=>!Array.isArray(c.paragraphs)))throw Error('Invalid book');const chapters=data.chapters.filter(c=>c.paragraphs.length>0);const weights=chapters.map(c=>c.paragraphs.reduce((s,p)=>s+(String(p).match(/\S+/g)||[]).length,0));const book={...data,chapters,meta,weights,total:weights.reduce((s,n)=>s+n,0)};booksCache.set(meta.id,book);return book;}
  const freshChapter=(book)=>{const i=book.chapters.findIndex(ch=>!['dedication','epigraph'].includes(ch.id));return Math.max(0,i);};
  async function openBook(id,explicit){
    const meta=catalog.find(b=>b.id===id);if(!meta)return;const token=++openToken;
    if(current)savePosition();$('library-main').setAttribute('aria-busy','true');
    try{const book=await getBook(meta);if(token!==openToken)return;current=book;const position=explicit||saved.positions[id]||{chapter:freshChapter(book),paragraph:0,offset:0,atTop:true};chapterIndex=Math.round(clamp(position.chapter,0,book.chapters.length-1));
      saved.lastBookId=id;$('library-view').hidden=true;$('reader-view').hidden=false;document.body.style.overflow='hidden';$('reader-book-title').textContent=meta.title;$('reader-author').textContent=meta.author;applySettings();renderChapter(position);persist();document.title=`${meta.title} · NOCTURNE`;
      if(location.hash!==`#read/${id}`)history.pushState({reader:id},'',`#read/${id}`);
    }catch(error){toast(t('loadBookError'));console.error('Book load failed:',error.message);}finally{$('library-main').removeAttribute('aria-busy');}
  }
  function paragraphNodes(){return [...$('chapter-text').children];}
  function captureAnchor(){const scroll=$('reading-scroll'),nodes=paragraphNodes(),edge=scroll.getBoundingClientRect().top+28;let paragraph=nodes.findIndex(p=>p.getBoundingClientRect().bottom>edge);if(paragraph<0)paragraph=Math.max(0,nodes.length-1);const node=nodes[paragraph];return {chapter:chapterIndex,paragraph,offset:node?Math.max(0,edge-node.getBoundingClientRect().top):0,atTop:scroll.scrollTop<15};}
  function restoreAnchor(position){restoring=true;requestAnimationFrame(()=>{const scroll=$('reading-scroll'),nodes=paragraphNodes(),p=nodes[Math.round(clamp(position.paragraph,0,Math.max(0,nodes.length-1)))];if(position.atTop||!p)scroll.scrollTop=0;else scroll.scrollTop+=p.getBoundingClientRect().top-scroll.getBoundingClientRect().top-28+clamp(position.offset||0,0,p.offsetHeight);requestAnimationFrame(()=>{restoring=false;updateProgress();savePosition();scroll.focus({preventScroll:true});});});}
  function renderChapter(position={chapter:chapterIndex,paragraph:0,offset:0,atTop:true}){
    if(!current)return;const chapter=current.chapters[chapterIndex];$('chapter-label').lang=locale;$('chapter-label').textContent=`${String(chapterIndex+1).padStart(2,'0')} / ${String(current.chapters.length).padStart(2,'0')} · ${t('originalText')}`;$('chapter-title').textContent=chapter.title;$('footer-chapter').textContent=chapter.title;
    const fragment=document.createDocumentFragment();chapter.paragraphs.forEach((text,i)=>{const p=document.createElement('p');p.textContent=text;p.id=`paragraph-${i}`;p.dataset.index=i;fragment.appendChild(p);});$('chapter-text').replaceChildren(fragment);
    $('previous-chapter').disabled=chapterIndex===0;$('next-chapter').disabled=chapterIndex===current.chapters.length-1;$('previous-title').textContent=current.chapters[chapterIndex-1]?.title||'';$('next-title').textContent=current.chapters[chapterIndex+1]?.title||'';$('chapter-count').textContent=`${chapterIndex+1} / ${current.chapters.length}`;$('book-finished').hidden=chapterIndex!==current.chapters.length-1;
    updateBookmarkButton(position);restoreAnchor(position);
  }
  function progress(){if(!current)return {percent:0,remaining:0};const scroll=$('reading-scroll'),range=scroll.scrollHeight-scroll.clientHeight;const fraction=range>1?clamp(scroll.scrollTop/range,0,1):(scroll.scrollTop>0?1:0);const before=current.weights.slice(0,chapterIndex).reduce((s,w)=>s+w,0);const read=before+current.weights[chapterIndex]*fraction;return {percent:clamp(read/(current.total||1)*100,0,100),remaining:Math.ceil((current.total-read)/220)};}
  function updateProgress(){if(!current)return;const p=progress();$('reader-progress-bar').style.width=`${p.percent}%`;$('reader-progress-label').textContent=`${Math.round(p.percent)}%`;$('reader-progress-label').setAttribute('aria-label',t('progress',{n:Math.round(p.percent)}));$('reader-time-left').textContent=t('remaining',{time:duration(p.remaining)});updateBookmarkButton(captureAnchor());}
  function savePosition(){if(!current||restoring)return;const position={...captureAnchor(),percent:progress().percent,updatedAt:new Date().toISOString()};saved.positions[current.id]=position;saved.lastBookId=current.id;persist();}
  function changeChapter(delta){if(!current)return;const next=chapterIndex+delta;if(next<0||next>=current.chapters.length)return;savePosition();chapterIndex=next;renderChapter();}
  function backLibrary(updateHistory=true){savePosition();document.querySelectorAll('dialog[open]').forEach(d=>d.close());openToken++;current=null;$('reader-view').hidden=true;$('library-view').hidden=false;document.body.style.overflow='';setFocusMode(false);renderShelf();document.title=t('title');if(updateHistory&&location.hash.startsWith('#read/'))history.pushState({},'',location.pathname+location.search);$('library-main').focus({preventScroll:true});}
  function applySettings(){const s=saved.settings,reader=$('reader-view');reader.style.setProperty('--reading-size',`${s.size}px`);reader.style.setProperty('--reading-line',s.line);reader.style.setProperty('--reading-width',`${s.width}px`);reader.style.setProperty('--reading-light',Math.round(s.brightness*2.55));$('reading-page').classList.toggle('sans',s.font==='sans');$('font-serif').setAttribute('aria-pressed',s.font==='serif');$('font-sans').setAttribute('aria-pressed',s.font==='sans');
    for(const [id,key,suffix] of [['font-size','size','px'],['line-height','line',''],['reading-width','width','px'],['text-brightness','brightness','%']]){$(id).value=s[key];$(`${id}-value`).value=`${s[key]}${suffix}`;}
    const preview=document.querySelector('.type-preview');preview.style.fontSize=`${s.size}px`;preview.style.lineHeight=s.line;preview.style.fontFamily=s.font==='sans'?'Arial,sans-serif':'Georgia,serif';preview.style.color=`rgb(${Math.round(s.brightness*2.55)},${Math.round(s.brightness*2.55)},${Math.round(s.brightness*2.55)})`;
  }
  function updateSettings(change){const anchor=current?captureAnchor():null;saved.settings={...saved.settings,...change};applySettings();persist();if(anchor)restoreAnchor(anchor);}
  function setFocusMode(on){focusMode=on;$('reader-view').classList.toggle('focus-mode',on);$('exit-focus').hidden=!on;$('reader-focus').setAttribute('aria-label',t(on?'focusOff':'focusOn'));}
  function openDialog(id){const dialog=$(id);if(!dialog.open)dialog.showModal();}
  function showContents(){if(!current)return;$('contents-book').textContent=current.meta.title;$('contents-list').innerHTML=current.chapters.map((chapter,i)=>`<button class="toc-row" data-chapter="${i}" aria-current="${i===chapterIndex}"><small>${String(i+1).padStart(2,'0')}</small><span>${esc(chapter.title)}</span></button>`).join('');openDialog('contents-dialog');requestAnimationFrame(()=>$('contents-list').querySelector('[aria-current="true"]')?.scrollIntoView({block:'nearest'}));}
  function updateBookmarkButton(anchor){if(!current)return;const found=saved.bookmarks.some(b=>b.bookId===current.id&&b.chapter===chapterIndex&&b.paragraph===anchor.paragraph);$('reader-bookmark').setAttribute('aria-pressed',found);$('reader-bookmark').setAttribute('aria-label',t(found?'unbookmark':'bookmark'));$('reader-bookmark').innerHTML=`<svg width="18" height="21" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4Z" fill="${found?'currentColor':'none'}" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>`;}
  function toggleBookmark(){if(!current)return;const a=captureAnchor(),index=saved.bookmarks.findIndex(b=>b.bookId===current.id&&b.chapter===chapterIndex&&b.paragraph===a.paragraph);if(index>=0){saved.bookmarks.splice(index,1);toast(t('bookmarkRemoved'));}else{saved.bookmarks.push({id:`${Date.now()}-${Math.random().toString(36).slice(2,8)}`,bookId:current.id,chapter:chapterIndex,paragraph:a.paragraph,offset:a.offset,atTop:a.atTop,quote:current.chapters[chapterIndex].paragraphs[a.paragraph]?.slice(0,140)||'',createdAt:new Date().toISOString()});toast(t('bookmarkAdded'));}persist();updateBookmarkButton(a);$('bookmark-count').textContent=saved.bookmarks.length;}
  function showBookmarks(){const rows=saved.bookmarks.filter(b=>catalog.some(c=>c.id===b.bookId)).slice().reverse();$('bookmarks-list').innerHTML=rows.length?rows.map(b=>{const meta=catalog.find(c=>c.id===b.bookId);return `<div class="bookmark-item"><button data-open-bookmark="${esc(b.id)}"><strong lang="en">${esc(meta.title)}</strong><q lang="en">${esc(b.quote)}</q><small>${esc(meta.author)} · ${t('section',{n:b.chapter+1})}</small></button><button class="remove-bookmark" data-remove-bookmark="${esc(b.id)}" aria-label="${esc(t('removeBookmark',{title:meta.title}))}">×</button></div>`;}).join(''):`<p class="empty-bookmarks">${t('emptyBookmarks')}</p>`;openDialog('bookmarks-dialog');}
  function showSources(id){const rows=id?catalog.filter(b=>b.id===id):catalog;$('sources-list').innerHTML=rows.map(book=>`<section class="source-entry"><h3 lang="en">${esc(book.title)}</h3><small>${esc(book.author)} · ${book.publishedYear} · ${t('originalLanguage',{language:book.language.toUpperCase()})}</small><p>${t('sourceInfo',{year:book.authorDeathYear})}</p><p>${t('rightsInfo',{end:book.authorDeathYear+70})}</p><div class="source-links"><a href="${esc(book.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t('edition')}</a><a href="${esc(book.sourceRepository)}/tree/${esc(book.sourceCommit)}" target="_blank" rel="noopener noreferrer">${t('pinnedSource')}</a><a href="${esc(book.licenseUrl)}" target="_blank" rel="noopener noreferrer">CC0 1.0 ↗</a><a href="data/${esc(book.txt)}" download="${esc(book.id)}.txt">${t('download')}</a></div></section>`).join('');openDialog('sources-dialog');}

  $('book-grid').addEventListener('click',e=>{const b=e.target.closest('[data-book]');if(b)openBook(b.dataset.book);});$('featured').addEventListener('click',e=>{const b=e.target.closest('[data-book]');if(b)openBook(b.dataset.book);});
  $('search').addEventListener('input',renderShelf);$('filters').addEventListener('click',e=>{const button=e.target.closest('[data-filter]');if(!button)return;filter=button.dataset.filter;document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button);});renderShelf();});
  $('continue-reading').addEventListener('click',()=>openBook(saved.lastBookId));$('back-library').addEventListener('click',()=>backLibrary());$('finish-library').addEventListener('click',()=>backLibrary());$('previous-chapter').addEventListener('click',()=>changeChapter(-1));$('next-chapter').addEventListener('click',()=>changeChapter(1));
  $('reading-scroll').addEventListener('scroll',()=>{if(restoring)return;updateProgress();clearTimeout(scrollTimer);scrollTimer=setTimeout(savePosition,180);},{passive:true});
  $('reader-toc').addEventListener('click',showContents);$('footer-toc').addEventListener('click',showContents);$('reader-settings').addEventListener('click',()=>openDialog('settings-dialog'));$('reader-bookmark').addEventListener('click',toggleBookmark);$('reader-focus').addEventListener('click',()=>{const a=captureAnchor();setFocusMode(!focusMode);restoreAnchor(a);});$('exit-focus').addEventListener('click',()=>{const a=captureAnchor();setFocusMode(false);restoreAnchor(a);});
  $('contents-list').addEventListener('click',e=>{const button=e.target.closest('[data-chapter]');if(!button||!current)return;savePosition();chapterIndex=clamp(button.dataset.chapter,0,current.chapters.length-1);$('contents-dialog').close();renderChapter();});
  $('library-bookmarks').addEventListener('click',showBookmarks);$('bookmarks-list').addEventListener('click',e=>{const remove=e.target.closest('[data-remove-bookmark]');if(remove){saved.bookmarks=saved.bookmarks.filter(b=>b.id!==remove.dataset.removeBookmark);persist();renderShelf();showBookmarks();return;}const open=e.target.closest('[data-open-bookmark]');if(open){const mark=saved.bookmarks.find(b=>b.id===open.dataset.openBookmark);if(mark){$('bookmarks-dialog').close();openBook(mark.bookId,mark);}}});
  $('library-sources').addEventListener('click',()=>showSources());$('reader-sources').addEventListener('click',()=>showSources(current?.id));
  for(const [id,key]of [['font-size','size'],['line-height','line'],['reading-width','width'],['text-brightness','brightness']])$(id).addEventListener('input',e=>updateSettings({[key]:Number(e.target.value)}));
  document.querySelectorAll('[data-font]').forEach(button=>button.addEventListener('click',()=>updateSettings({font:button.dataset.font})));$('reset-settings').addEventListener('click',()=>updateSettings({...defaults}));
  document.querySelectorAll('.close-dialog').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}}));
  document.addEventListener('keydown',e=>{const editing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'');if(editing||document.querySelector('dialog[open]'))return;if(e.key==='/'&&!current){e.preventDefault();$('search').focus();}if(current&&e.key==='ArrowRight'){e.preventDefault();changeChapter(1);}if(current&&e.key==='ArrowLeft'){e.preventDefault();changeChapter(-1);}if(current&&e.key==='Escape'){if(focusMode){const a=captureAnchor();setFocusMode(false);restoreAnchor(a);}else backLibrary();}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)savePosition();});window.addEventListener('pagehide',savePosition);window.addEventListener('popstate',()=>{const match=location.hash.match(/^#read\/([a-z0-9-]+)$/);if(match){if(current?.id!==match[1])openBook(match[1]);}else if(current)backLibrary(false);});
  applySettings();
  fetchJson('data/catalog.json').then(data=>{if(!Array.isArray(data.books)||!data.books.length)throw Error('Empty catalog');catalog=data.books;$('shelf-count').textContent=t('shelfCount',{n:catalog.length});renderFeatured();renderShelf();const match=location.hash.match(/^#read\/([a-z0-9-]+)$/);if(match)openBook(match[1]);}).catch(error=>{$('featured').innerHTML=`<div class="loading-state">${t('loadLibraryError')}<br><br><button class="text-button" id="retry-load">${t('retry')}</button></div>`;$('shelf-count').textContent=t('checkConnection');$('retry-load').addEventListener('click',()=>location.reload());console.error('Catalog load failed:',error.message);});
})();
